#include <bits/stdc++.h>
using namespace std;

static const int MOD = 998244353;

static inline bool canBeMedian(
    int n,
    int i,
    int v,
    int s,
    int side
){
    int r = v-1-s;
    int pos = side?s+1:n-r;
    if(pos<=i){
        int smaller = s+min(r, max(0, i-(n-r)));
        if(smaller == (i-1)/2) return true;
    }
    if(pos>=i){
        int smaller = r + max(0, s- i +1);
        if(smaller == (n-i)/2) return true;
    }
    return false;
}

int main() {
	// your code goes here
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>> n;
        vector<int> a(n+1);
        for(int i=1; i<=n; ++i) cin>>a[i];
        if(n==1){
            cout<<(a[1] == 1 ? 1: 0) <<endl;
            continue;
        }
        vector<vector<unsigned char>> ok(n);
        for(int v=1; v<n; ++v){
            ok[v].assign(v, 3);
        }
        vector<vector<int>> idxOf(n+1);
        for(int i=1; i<=n; i++){
            if(a[i] < n) idxOf[a[i]].push_back(i);
        }
        
        for(int v = 1; v<n; v++){
            if(idxOf[v].empty()) continue;
            for(int s = 0; s<v; ++s){
                unsigned char mask = 0;
                for(int i:idxOf[v]){
                    if(canBeMedian(n, i, v, s, 0)){
                        mask|=1; break;
                    }
                }
                for(int i:idxOf[v]){
                    if(canBeMedian(n, i, v, s, 1)){
                        mask|=2; break;
                    }
                }
                mask = 3;
                for(int i: idxOf[v]){
                    unsigned char m = 0;
                    if(canBeMedian(n, i, v, s, 0)) m|=1;
                    if(canBeMedian(n, i, v, s, 1)) m|=2;
                    mask&=m;
                    if(mask == 0) break;
                }
                ok[v][s] = mask;
            }
        }
        
        int requiredL = -1;
        bool impossible = false;
        for(int i=1; i<=n; i++){
            if(a[i] !=n) continue;
            int need = (i==1) ? 0:(i==n)?n-1:-1;
            if(need == -1){
                impossible = true;
                break;
            }
            if(requiredL != -1 && requiredL!= need){
                impossible = true;
                break;
            }
            requiredL = need;
        }
        if(impossible){
            cout<<0<<endl;
            continue;
        }
        vector<int> dp(n, 0), ndp(n, 0);
        dp[0] = 1;
        for(int v = 1; v< n; ++v){
            fill(ndp.begin(), ndp.end(), 0);
            for(int s = 0; s<v; ++s){
                if(!dp[s]) continue;
                if(ok[v][s] & 1){
                    ndp[s]+=dp[s];
                    if(ndp[s] >= MOD) ndp[s] -= MOD;
                  
                }
                
                if(ok[v][s] & 2){
          
                    ndp[s+1] += dp[s];
                    if(ndp[s+1] >= MOD) ndp[s+1] -= MOD;
                }
            }
            dp.swap(ndp);
        }
        if(requiredL != -1){
            cout << dp[requiredL] <<endl;
        }
        else {
            long long ans = 0;

            for(int s= 0; s<=n-1; ++s){
                ans+=dp[s];
                if(ans>=MOD) ans-=MOD;
            }
            cout<<ans<<endl;
        }
    }
    return 0;
}
